INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (118, 'ruoyi-exam-answer.yml', 'DEFAULT_GROUP', 'spring:\r\n  datasource:\r\n    dynamic:\r\n      # 设置默认的数据源或者数据源组,默认值即为 master\r\n      primary: master\r\n      datasource:\r\n        # 主库数据源 答卷成绩库(独立库 高并发大表)\r\n        master:\r\n          type: ${spring.datasource.type}\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: ${datasource.exam-answer.url}\r\n          username: ${datasource.exam-answer.username}\r\n          password: ${datasource.exam-answer.password}\r\n', '5f3ef8b5c0c0b8f0a0f31091c16ebcb0', '2026-09-30 13:35:23', '2026-09-30 13:35:23', 'nacos', '0:0:0:0:0:0:0:1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (119, 'ruoyi-exam-practice.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源 考试主库(练习记录与错题本归主库便于与题目/试卷联查)\n        master:\n          type: ${spring.datasource.type}\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.exam.url}\n          username: ${datasource.exam.username}\n          password: ${datasource.exam.password}\n', 'ed701074d690f439b4d66031f5e7a2c0', '2026-09-30 21:49:28', '2026-09-30 21:49:28', 'nacos', '0:0:0:0:0:0:0:1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (120, 'ruoyi-exam-mark.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源 考试主库\n        master:\n          type: ${spring.datasource.type}\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.exam.url}\n          username: ${datasource.exam.username}\n          password: ${datasource.exam.password}\n', '88184bbc737c31594239b3d2879fe2c3', '2026-10-01 10:29:08', '2026-10-01 10:29:08', 'nacos', '0:0:0:0:0:0:0:1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (121, 'ruoyi-exam-proctor.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源 考试主库(防作弊任务与事件归主库便于与考试/答卷关联)\n        master:\n          type: ${spring.datasource.type}\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.exam.url}\n          username: ${datasource.exam.username}\n          password: ${datasource.exam.password}\n', '428fbe597127fc5ab2dd128c3fd4e96a', '2026-10-02 00:06:10', '2026-10-02 00:06:10', 'nacos', '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
