INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (10, 12, 'ruoyi-workflow.yml', 'DEFAULT_GROUP', '', '# 将项目路径：config/下对应文件中内容复制到此处', '2944a25cb97926efcaa43b3ad7a64cf0', '2026-09-28 14:52:20', '2026-09-28 06:52:21', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"c_desc\":\"工作流服务\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (12, 13, 'seata-server.properties', 'DEFAULT_GROUP', '', '# 将项目路径：config/下对应文件中内容复制到此处', '2944a25cb97926efcaa43b3ad7a64cf0', '2026-09-28 14:52:56', '2026-09-28 06:52:57', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"properties\",\"c_desc\":\"seata配置文件\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (14, 14, 'ruoyi-snailjob-server.yml', 'DEFAULT_GROUP', '', '# 将项目路径：config/下对应文件中内容复制到此处', '2944a25cb97926efcaa43b3ad7a64cf0', '2026-09-28 14:53:08', '2026-09-28 06:53:09', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"c_desc\":\"SJ定时任务控制台\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 15, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /resource/sse/close\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n      - /warm-flow-ui/**\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      server:\n        webflux:\n          # Gateway WebFlux 转发使用的 Reactor Netty 连接池配置\n          httpclient:\n            pool:\n              # 使用固定连接池，避免 SSE 长连接占满默认连接池后快速拒绝普通请求\n              type: fixed\n              # 总最大连接数\n              max-connections: 1000\n              # 连接池满时等待可用连接的时间，单位毫秒\n              acquire-timeout: 3000\n              # 空闲连接最大保留时间\n              max-idle-time: 30s\n              # 后台空闲连接回收间隔\n              eviction-interval: 30s\n            # SSE 场景通常不设置响应超时，避免长连接被网关主动断开\n            # response-timeout: 60s\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/tool/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**,/monitor/**\n              filters:\n                - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n', '1c85fcdb7f215c49b37b271edf8f5d68', '2026-09-28 16:30:07', '2026-09-28 08:30:08', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 16, 'ruoyi-exam-question.yml', 'DEFAULT_GROUP', '', 'spring:\r\n  datasource:\r\n    dynamic:\r\n      # 设置默认的数据源或者数据源组,默认值即为 master\r\n      primary: master\r\n      datasource:\r\n        # 主库数据源 考试主库\r\n        master:\r\n          type: ${spring.datasource.type}\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: ${datasource.exam.url}\r\n          username: ${datasource.exam.username}\r\n          password: ${datasource.exam.password}\r\n', '1bdf9315553dc3cb462040cdb68654f2', '2026-09-28 16:35:43', '2026-09-28 08:35:44', 'nacos', '0:0:0:0:0:0:0:1', 'I', 'dev', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (2, 17, 'datasource.yml', 'DEFAULT_GROUP', '', 'datasource:\n  system-master:\n    # jdbc 所有参数配置参考 https://lionli.blog.csdn.net/article/details/122018562\n    # rewriteBatchedStatements=true 批处理优化 大幅提升批量插入更新删除性能\n    url: jdbc:mysql://8.137.151.232:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    password: ruoyi123\n  gen:\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    password: password\n  job:\n    url: jdbc:mysql://localhost:3306/ry-job?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    password: password\n  workflow:\n    url: jdbc:mysql://localhost:3306/ry-workflow?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true\n    username: root\n    password: password\n#  system-oracle:\n#    url: jdbc:oracle:thin:@//localhost:1521/XE\n#    username: ROOT\n#    password: password\n#  system-postgres:\n#    url: jdbc:postgresql://localhost:5432/postgres?useUnicode=true&characterEncoding=utf8&useSSL=true&autoReconnect=true&reWriteBatchedInserts=true\n#    username: root\n#    password: password\n\nspring:\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    # 动态数据源文档 https://www.kancloud.cn/tracy5546/dynamic-datasource/content\n    dynamic:\n      # 性能分析插件(有性能损耗 不建议生产环境使用)\n      p6spy: true\n      # 开启seata代理，开启后默认每个数据源都代理，如果某个不需要代理可单独关闭\n      seata: ${seata.enabled}\n      # 严格模式 匹配不到数据源则报错\n      strict: true\n      hikari:\n        # 最大连接池数量\n        maxPoolSize: 20\n        # 最小空闲线程数量\n        minIdle: 10\n        # 配置获取连接等待超时的时间\n        connectionTimeout: 30000\n        # 校验超时时间\n        validationTimeout: 5000\n        # 空闲连接存活最大时间，默认10分钟\n        idleTimeout: 600000\n        # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认30分钟\n        maxLifetime: 1800000\n        # 多久检查一次连接的活性\n        keepaliveTime: 30000\n', '1672c7fa379946e9fd38190f5daaa5e3', '2026-09-28 16:38:04', '2026-09-28 08:38:05', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"数据源配置\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (2, 18, 'datasource.yml', 'DEFAULT_GROUP', '', 'datasource:\n  system-master:\n    # jdbc 所有参数配置参考 https://lionli.blog.csdn.net/article/details/122018562\n    # rewriteBatchedStatements=true 批处理优化 大幅提升批量插入更新删除性能\n    url: jdbc:mysql://8.137.151.232:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    ruoyi123: ruoyi123\n  gen:\n    url: jdbc:mysql://8.137.151.232:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    ruoyi123: ruoyi123\n  job:\n    url: jdbc:mysql://8.137.151.232:3306/ry-job?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    ruoyi123: ruoyi123\n  workflow:\n    url: jdbc:mysql://8.137.151.232:3306/ry-workflow?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true\n    username: root\n    ruoyi123: ruoyi123\n  # 考试主库 题库/试卷/考试/阅卷/统计\n  exam:\n    url: jdbc:mysql://8.137.151.232:3306/ry-exam?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    ruoyi123: ruoyi123\n  # 答卷成绩库 高并发大表 独立库便于分库分表\n  exam-answer:\n    url: jdbc:mysql://8.137.151.232:3306/ry-exam-answer?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8&rewriteBatchedStatements=true&allowPublicKeyRetrieval=true\n    username: root\n    ruoyi123: ruoyi123\n#  system-oracle:\n#    url: jdbc:oracle:thin:@//8.137.151.232:1521/XE\n#    username: ROOT\n#    ruoyi123: ruoyi123\n#  system-postgres:\n#    url: jdbc:postgresql://8.137.151.232:5432/postgres?useUnicode=true&characterEncoding=utf8&useSSL=true&autoReconnect=true&reWriteBatchedInserts=true\n#    username: root\n#    ruoyi123: ruoyi123\n\nspring:\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    # 动态数据源文档 https://www.kancloud.cn/tracy5546/dynamic-datasource/content\n    dynamic:\n      # 性能分析插件(有性能损耗 不建议生产环境使用)\n      p6spy: true\n      # 开启seata代理，开启后默认每个数据源都代理，如果某个不需要代理可单独关闭\n      seata: ${seata.enabled}\n      # 严格模式 匹配不到数据源则报错\n      strict: true\n      hikari:\n        # 最大连接池数量\n        maxPoolSize: 20\n        # 最小空闲线程数量\n        minIdle: 10\n        # 配置获取连接等待超时的时间\n        connectionTimeout: 30000\n        # 校验超时时间\n        validationTimeout: 5000\n        # 空闲连接存活最大时间，默认10分钟\n        idleTimeout: 600000\n        # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认30分钟\n        maxLifetime: 1800000\n        # 多久检查一次连接的活性\n        keepaliveTime: 30000\n', '2d588520966cd5ef94bbc999cef65f59', '2026-09-28 16:41:26', '2026-09-28 08:41:27', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"数据源配置\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 19, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /resource/sse/close\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n      - /warm-flow-ui/**\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      server:\n        webflux:\n          # Gateway WebFlux 转发使用的 Reactor Netty 连接池配置\n          httpclient:\n            pool:\n              # 使用固定连接池，避免 SSE 长连接占满默认连接池后快速拒绝普通请求\n              type: fixed\n              # 总最大连接数\n              max-connections: 1000\n              # 连接池满时等待可用连接的时间，单位毫秒\n              acquire-timeout: 3000\n              # 空闲连接最大保留时间\n              max-idle-time: 30s\n              # 后台空闲连接回收间隔\n              eviction-interval: 30s\n            # SSE 场景通常不设置响应超时，避免长连接被网关主动断开\n            # response-timeout: 60s\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/tool/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**,/monitor/**\n              filters:\n                - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                - StripPrefix=1\n', '55b1679228bf6f2decad0334d981ef69', '2026-09-28 16:53:49', '2026-09-28 08:53:49', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
