             - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                # - StripPrefix=1\n', '8a1bb7e97e0c88ffe96c1d36261fda6f', '2026-09-28 17:05:59', '2026-09-28 09:05:59', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 21, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /resource/sse/close\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n      - /warm-flow-ui/**\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      server:\n        webflux:\n          # Gateway WebFlux 转发使用的 Reactor Netty 连接池配置\n          httpclient:\n            pool:\n              # 使用固定连接池，避免 SSE 长连接占满默认连接池后快速拒绝普通请求\n              type: fixed\n              # 总最大连接数\n              max-connections: 1000\n              # 连接池满时等待可用连接的时间，单位毫秒\n              acquire-timeout: 3000\n              # 空闲连接最大保留时间\n              max-idle-time: 30s\n              # 后台空闲连接回收间隔\n              eviction-interval: 30s\n            # SSE 场景通常不设置响应超时，避免长连接被网关主动断开\n            # response-timeout: 60s\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/tool/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**,/monitor/**\n              filters:\n                - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-bank\n              uri: lb://ruoyi-exam-bank\n              predicates:\n                - Path=/bank/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                # - StripPrefix=1\n', '8c3572aee7d5b833dad541d10faf9b60', '2026-09-28 17:11:15', '2026-09-28 09:11:15', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
