             - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**,/bank/**,/media/**,/option/**,/tag/**,/tagRel/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                # - StripPrefix=1\n', 'd7ec2bf50ff485e6603cfb3c50366370', '2026-09-29 11:39:15', '2026-09-29 03:39:15', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (1, 24, 'application-common.yml', 'DEFAULT_GROUP', '', 'server:\n  # undertow 配置\n  undertow:\n    # HTTP post内容的最大大小。当值为-1时，默认值为大小是无限的\n    max-http-post-size: 1GB\n    # 以下的配置会影响buffer,这些buffer会用于服务器连接的IO操作,有点类似netty的池化内存管理\n    # 每块buffer的空间大小,越小的空间被利用越充分\n    buffer-size: 512\n    # 是否分配的直接内存\n    direct-buffers: true\n    threads:\n      # 设置IO线程数, 它主要执行非阻塞的任务,它们会负责多个连接, 默认设置每个CPU核心一个线程\n      io: 8\n      # 阻塞任务线程池, 当执行类似servlet请求阻塞操作, undertow会从这个线程池中取得线程,它的值设置取决于系统的负载\n      worker: 256\n\ndubbo:\n  application:\n    # 关闭qos端口避免单机多生产者端口冲突 如需使用自行开启\n    qos-enable: false\n  protocol:\n    # 如需使用 Triple 3.0 新协议 可查看官方文档\n    # 使用 dubbo 协议通信\n    name: dubbo\n    # dubbo 协议端口(-1表示自增端口,从20880开始)\n    port: -1\n    # 指定dubbo协议注册ip\n    # host: 192.168.0.100\n    # 开启虚拟线程\n    # threadpool: virtual\n  # 消费者相关配置\n  consumer:\n    # 超时时间\n    timeout: 3000\n  # 自定义配置\n  custom:\n    # 全局请求log\n    request-log: true\n    # info 基础信息 param 参数信息 full 全部\n    log-level: info\n\nspring:\n  threads:\n    # 开启虚拟线程 仅jdk21可用\n    virtual:\n      enabled: false\n  task:\n    execution:\n      # 从 springboot 3.5 开始 spring自带线程池\n      # 不再需要 AsyncConfig与ThreadPoolConfig 可直接注入线程池使用\n      thread-name-prefix: async-\n      # 由spring自己初始化线程池\n      mode: force\n  # 资源信息\n  messages:\n    # 国际化资源文件路径\n    basename: i18n/messages\n  servlet:\n    multipart:\n      # 整个请求大小限制\n      max-request-size: 20MB\n      # 上传单个文件大小限制\n      max-file-size: 10MB\n  mvc:\n    # 设置静态资源路径 防止所有请求都去查静态资源\n    static-path-pattern: /static/**\n    format:\n      date-time: yyyy-MM-dd HH:mm:ss\n  #jackson配置\n  jackson:\n    # 日期格式化\n    date-format: yyyy-MM-dd HH:mm:ss\n    serialization:\n      # 格式化输出\n      INDENT_OUTPUT: false\n      # 忽略无法转换的对象\n      fail_on_empty_beans: false\n    deserialization:\n      # 允许对象忽略json中不存在的属性\n      fail_on_unknown_properties: false\n  cloud:\n    inetutils:\n      # 指定全局使用ip网段\n      preferred-networks:\n#        - 192.168\n#        - 10.0\n    nacos:\n      discovery:\n        metadata:\n          # admin 监控账号密码\n          username: ruoyi\n          userpassword: 123456\n    bus:\n      id: ${spring.application.name}\n      base-packages: org.dromara.**.event\n  # 消息总线 也可以使用 kafka 参考 spring-cloud-bus 用法\n  rabbitmq:\n    host: localhost\n    port: 5672\n    username: ruoyi\n    password: ruoyi123\n\n  # redis通用配置 子服务可以自行配置进行覆盖\n  data:\n    redis:\n      host: 8.137.151.232\n      port: 6379\n      # redis 密码必须配置\n      password: ruoyi123\n      database: 0\n      # 需要使用数字\n      timeout: 10000\n      ssl.enabled: false\n\n# redisson 配置\nredisson:\n  # redis key前缀\n  keyPrefix:\n  # 线程池数量\n  threads: 4\n  # Netty线程池数量\n  nettyThreads: 8\n  # 单节点配置\n  singleServerConfig:\n    # 客户端名称\n    clientName: ${spring.application.name}\n    # 最小空闲连接数\n    connectionMinimumIdleSize: 8\n    # 连接池大小\n    connectionPoolSize: 32\n    # 连接空闲超时，单位：毫秒\n    idleConnectionTimeout: 10000\n    # 命令等待超时，单位：毫秒\n    timeout: 3000\n    # 发布和订阅连接池大小\n    subscriptionConnectionPoolSize: 50\n\n# 分布式锁 lock4j 全局配置\nlock4j:\n  # 获取分布式锁超时时间，默认为 3000 毫秒\n  acquire-timeout: 3000\n  # 分布式锁的超时时间，默认为 30 秒\n  expire: 30000\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    health:\n      show-details: ALWAYS\n    logfile:\n      external-file: ./logs/${spring.application.name}/console.log\n\n# 日志配置\nlogging:\n  level:\n    org.springframework: warn\n    org.apache.dubbo: error\n    com.alibaba.nacos: error\n    org.mybatis.spring.mapper: error\n    org.apache.fury: warn\n    io.micrometer: error\n    # 临时处理 spring 调整日志级别导致启动警告问题 不影响使用等待 alibaba 适配\n    org.springframework.context.support.PostProcessorRegistrationDelegate: error\n  config: classpath:logback-plus.xml\n\n# Sa-Token配置\nsa-token:\n  # token名称 (同时也是cookie名称)\n  token-name: Authorization\n  # 开启内网服务调用鉴权(不允许越过gateway访问内网服务 保障服务安全)\n  check-same-token: true\n  # 是否允许同一账号并发登录 (为true时允许一起登录, 为false时新登录挤掉旧登录)\n  is-concurrent: true\n  # 在多人登录同一账号时，是否共用一个token (为true时所有登录共用一个token, 为false时每次登录新建一个token)\n  is-share: false\n  # jwt秘钥\n  jwt-secret-key: abcdefghijklmnopqrstuvwxyz\n\n# MyBatisPlus配置\n# https://baomidou.com/config/\nmybatis-plus:\n  # 自定义配置 是否全局开启逻辑删除 关闭后 所有逻辑删除功能将失效\n  enableLogicDelete: true\n  # 多包名使用 例如 org.dromara.**.mapper,org.xxx.**.mapper\n  mapperPackage: org.dromara.**.mapper\n  # 对应的 XML 文件位置\n  mapperLocations: classpath*:mapper/**/*Mapper.xml\n  # 实体扫描，多个package用逗号或者分号分隔\n  typeAliasesPackage: org.dromara.**.domain\n  global-config:\n    dbConfig:\n      # 主键类型\n      # AUTO 自增 NONE 空 INPUT 用户输入 ASSIGN_ID 雪花 ASSIGN_UUID 唯一 UUID\n      # 如需改为自增 需要将数据库表全部设置为自增\n      idType: ASSIGN_ID\n\n# 数据加密\nmybatis-encryptor:\n  # 是否开启加密\n  enable: false\n  # 默认加密算法\n  algorithm: BASE64\n  # 编码方式 BASE64/HEX。默认BASE64\n  encode: BASE64\n  # 安全秘钥 对称算法的秘钥 如：AES，SM4\n  password:\n  # 公私钥 非对称算法的公私钥 如：SM2，RSA\n  publicKey:\n  privateKey:\n\n# api接口加密\napi-decrypt:\n  # 是否开启全局接口加密\n  enabled: true\n  # AES 加密头标识\n  headerFlag: encrypt-key\n  # 响应加密公钥 非对称算法的公私钥 如：SM2，RSA 使用者请自行更换\n  # 对应前端解密私钥 \n  publicKey: MFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAJnNwrj4hi/y3CCJu868ghCG5dUj8wZK++RNlTLcXoMmdZWEQ/u02RgD5LyLAXGjLOjbMtC+/J9qofpSGTKSx/MCAwEAAQ==\n  # 请求解密私钥 非对称算法的公私钥 如：SM2，RSA 使用者请自行更换\n  # 对应前端加密公钥 MFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAKoR8mX0rGKLqzcWmOzbfj64K8ZIgOdHnzkXSOVOZbFu/TJhZ7rFAN+eaGkl3C4buccQd/EjEsj9ir7ijT7h96MCAwEAAQ==\n  privateKey: \n\n# 防止XSS攻击\nxss:\n  enabled: true\n  excludeUrls:\n    - /system/notice\n    - /warm-flow/save-json\n\n# 接口文档配置\nspringdoc:\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'标题：RuoYi-Cloud-Plus微服务权限管理系统_接口文档\'\n    # 描述\n    description: \'描述：微服务权限管理系统, 具体包括XXX,XXX模块...\'\n    # 版本\n    version: \'版本号：系统版本...\'\n    # 作者信息\n    contact:\n      name: Lion Li\n      email: crazylionli@163.com\n      url: https://gitee.com/dromara/RuoYi-Cloud-Plus\n\n# seata配置\nseata:\n  # 是否启用\n  enabled: false\n  # Seata 应用编号，默认为应用名\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: ${spring.application.name}-group\n  config:\n    type: nacos\n    nacos:\n      server-addr: ${spring.cloud.nacos.server-addr}\n      group: ${spring.cloud.nacos.config.group}\n      namespace: ${spring.profiles.active}\n      username: ${spring.cloud.nacos.username}\n      password: ${spring.cloud.nacos.password}\n      data-id: seata-server.properties\n  registry:\n    type: nacos\n    nacos:\n      application: ruoyi-seata-server\n      server-addr: ${spring.cloud.nacos.server-addr}\n      group: ${spring.cloud.nacos.discovery.group}\n      username: ${spring.cloud.nacos.username}\n      password: ${spring.cloud.nacos.password}\n      namespace: ${spring.profiles.active}\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n\n# 多租户配置\ntenant:\n  # 是否开启\n  enable: true\n  # 排除表\n  excludes:\n    - sys_menu\n    - sys_tenant\n    - sys_tenant_package\n    - sys_role_dept\n    - sys_role_menu\n    - sys_user_post\n    - sys_user_role\n    - sys_client\n    - sys_oss_config\n    - flow_spel\n', '2b16c0f6b529b9cfbc14063a83a4d187', '2026-09-29 16:15:14', '2026-09-29 08:15:14', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"通用配置基础配置\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 25, 'ruoyi-exam-paper.yml', 'DEFAULT_GROUP', '', 'spring:\r\n  datasource:\r\n    dynamic:\r\n      # 设置默认的数据源或者数据源组,默认值即为 master\r\n      primary: master\r\n      datasource:\r\n        # 主库数据源 考试主库\r\n        master:\r\n          type: ${spring.datasource.type}\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: ${datasource.exam.url}\r\n          username: ${datasource.exam.username}\r\n          password: ${datasource.exam.password}\r\n', '1bdf9315553dc3cb462040cdb68654f2', '2026-09-29 17:45:32', '2026-09-29 09:45:32', 'nacos', '0:0:0:0:0:0:0:1', 'I', 'dev', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 26, 'ruoyi-exam-manage.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源 考试主库\n        master:\n          type: ${spring.datasource.type}\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.exam.url}\n          username: ${datasource.exam.username}\n          password: ${datasource.exam.password}\n', '88184bbc737c31594239b3d2879fe2c3', '2026-09-29 23:07:59', '2026-09-29 15:07:59', 'nacos', '0:0:0:0:0:0:0:1', 'I', 'dev', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 27, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /resource/sse/close\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n      - /warm-flow-ui/**\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      server:\n        webflux:\n          # Gateway WebFlux 转发使用的 Reactor Netty 连接池配置\n          httpclient:\n            pool:\n              # 使用固定连接池，避免 SSE 长连接占满默认连接池后快速拒绝普通请求\n              type: fixed\n              # 总最大连接数\n              max-connections: 1000\n              # 连接池满时等待可用连接的时间，单位毫秒\n              acquire-timeout: 3000\n              # 空闲连接最大保留时间\n              max-idle-time: 30s\n              # 后台空闲连接回收间隔\n              eviction-interval: 30s\n            # SSE 场景通常不设置响应超时，避免长连接被网关主动断开\n            # response-timeout: 60s\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/tool/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**,/monitor/**\n              filters:\n                - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**,/bank/**,/media/**,/option/**,/tag/**,/tagRel/**,/bankCategory/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                # - StripPrefix=1\n', '7cb17b8138eee996728ee788e7b14e58', '2026-09-30 12:50:14', '2026-09-30 04:50:15', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 28, 'ruoyi-exam-answer.yml', 'DEFAULT_GROUP', '', 'spring:\r\n  datasource:\r\n    dynamic:\r\n      # 设置默认的数据源或者数据源组,默认值即为 master\r\n      primary: master\r\n      datasource:\r\n        # 主库数据源 答卷成绩库(独立库 高并发大表)\r\n        master:\r\n          type: ${spring.datasource.type}\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: ${datasource.exam-answer.url}\r\n          username: ${datasource.exam-answer.username}\r\n          password: ${datasource.exam-answer.password}\r\n', '5f3ef8b5c0c0b8f0a0f31091c16ebcb0', '2026-09-30 13:35:22', '2026-09-30 05:35:23', 'nacos', '0:0:0:0:0:0:0:1', 'I', 'dev', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 29, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /resource/sse/close\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n      - /warm-flow-ui/**\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      server:\n        webflux:\n          # Gateway WebFlux 转发使用的 Reactor Netty 连接池配置\n          httpclient:\n            pool:\n              # 使用固定连接池，避免 SSE 长连接占满默认连接池后快速拒绝普通请求\n              type: fixed\n              # 总最大连接数\n              max-connections: 1000\n              # 连接池满时等待可用连接的时间，单位毫秒\n              acquire-timeout: 3000\n              # 空闲连接最大保留时间\n              max-idle-time: 30s\n              # 后台空闲连接回收间隔\n              eviction-interval: 30s\n            # SSE 场景通常不设置响应超时，避免长连接被网关主动断开\n            # response-timeout: 60s\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/tool/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**,/monitor/**\n              filters:\n                - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**,/bank/**,/media/**,/option/**,/tag/**,/tagRel/**,/bankCategory/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**,/invite/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                # - StripPrefix=1\n', 'f4cf87926fae09a655c00d7c2b49ef0c', '2026-09-30 13:36:25', '2026-09-30 05:36:25', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 30, 'ruoyi-gateway.yml', 'DEFAULT_GROUP', '', '# 安全配置\nsecurity:\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /resource/sse/close\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n      - /warm-flow-ui/**\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      server:\n        webflux:\n          # Gateway WebFlux 转发使用的 Reactor Netty 连接池配置\n          httpclient:\n            pool:\n              # 使用固定连接池，避免 SSE 长连接占满默认连接池后快速拒绝普通请求\n              type: fixed\n              # 总最大连接数\n              max-connections: 1000\n              # 连接池满时等待可用连接的时间，单位毫秒\n              acquire-timeout: 3000\n              # 空闲连接最大保留时间\n              max-idle-time: 30s\n              # 后台空闲连接回收间隔\n              eviction-interval: 30s\n            # SSE 场景通常不设置响应超时，避免长连接被网关主动断开\n            # response-timeout: 60s\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/tool/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**,/monitor/**\n              filters:\n                - StripPrefix=1\n            # 资源服务\n            - id: ruoyi-resource\n              uri: lb://ruoyi-resource\n              predicates:\n                - Path=/resource/**\n              filters:\n                - StripPrefix=1\n            # workflow服务\n            - id: ruoyi-workflow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/workflow/**\n              filters:\n                - StripPrefix=1\n            # warm-flow服务\n            - id: warm-flow\n              uri: lb://ruoyi-workflow\n              predicates:\n                - Path=/warm-flow-ui/**,/warm-flow/**\n            # 演示服务\n            - id: ruoyi-demo\n              uri: lb://ruoyi-demo\n              predicates:\n                - Path=/demo/**\n              filters:\n                - StripPrefix=1\n            # MQ演示服务\n            - id: ruoyi-test-mq\n              uri: lb://ruoyi-test-mq\n              predicates:\n                - Path=/test-mq/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-question\n              uri: lb://ruoyi-exam-question\n              predicates:\n                - Path=/question/**,/bank/**,/media/**,/option/**,/tag/**,/tagRel/**,/bankCategory/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-paper\n              uri: lb://ruoyi-exam-paper\n              predicates:\n                - Path=/paper/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-manage\n              uri: lb://ruoyi-exam-manage\n              predicates:\n                - Path=/exam/**,/invite/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-answer\n              uri: lb://ruoyi-exam-answer\n              predicates:\n                - Path=/answer/**\n              filters:\n                - StripPrefix=1\n            - id: ruoyi-exam-mark\n              uri: lb://ruoyi-exam-mark\n              predicates:\n                - Path=/mark/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-stat\n              uri: lb://ruoyi-exam-stat\n              predicates:\n                - Path=/stat/**\n              filters:\n                # - StripPrefix=1\n            - id: ruoyi-exam-ai\n              uri: lb://ruoyi-exam-ai\n              predicates:\n                - Path=/ai/**\n              filters:\n                # - StripPrefix=1\n', '892348fce80017071c6af28cb948b90b', '2026-09-30 21:48:47', '2026-09-30 13:48:47', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (0, 31, 'ruoyi-exam-practice.yml', 'DEFAULT_GROUP', '', 'spring:\n  datasource:\n    dynamic:\n      # 设置默认的数据源或者数据源组,默认值即为 master\n      primary: master\n      datasource:\n        # 主库数据源 考试主库(练习记录与错题本归主库便于与题目/试卷联查)\n        master:\n          type: ${spring.datasource.type}\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: ${datasource.exam.url}\n          username: ${datasource.exam.username}\n          password: ${datasource.exam.password}\n', 'ed701074d690f439b4d66031f5e7a2c0', '2026-09-30 21:49:27', '2026-09-30 13:49:27', 'nacos', '0:0:0:0:0:0:0:1', 'I', 'dev', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
